import{_ as s,o as e,c as i,ag as t}from"./chunks/framework.BZohXCq9.js";const u=JSON.parse('{"title":"混合架构 CI 的 APT 源：amd64 与 arm64 为什么要分开","description":"在同一条 CI 中正确配置 Ubuntu archive、ubuntu-ports、代理与镜像缓存","frontmatter":{"title":"混合架构 CI 的 APT 源：amd64 与 arm64 为什么要分开","description":"在同一条 CI 中正确配置 Ubuntu archive、ubuntu-ports、代理与镜像缓存","tags":["CI","Ubuntu","ARM64","APT","Docker"],"date":"2026/07/13"},"headers":[],"relativePath":"linux/mixed-arch-ci-apt.md","filePath":"linux/mixed-arch-ci-apt.md","lastUpdated":1784519165000}'),n={name:"linux/mixed-arch-ci-apt.md"};function r(p,a,c,l,o,d){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="混合架构-ci-的-apt-源-amd64-与-arm64-为什么要分开" tabindex="-1">混合架构 CI 的 APT 源：amd64 与 arm64 为什么要分开 <a class="header-anchor" href="#混合架构-ci-的-apt-源-amd64-与-arm64-为什么要分开" aria-label="Permalink to &quot;混合架构 CI 的 APT 源：amd64 与 arm64 为什么要分开&quot;">​</a></h1><p>同一套 CI 同时构建 amd64 工具和 arm64 板端包时，<code>apt update</code> 常出现 404、Release file 缺失、错误架构索引或镜像站偶发失败。根因往往不是网络本身，而是把两个 Ubuntu archive 拓扑当成一个源处理。</p><h2 id="ubuntu-的两个归档入口" tabindex="-1">Ubuntu 的两个归档入口 <a class="header-anchor" href="#ubuntu-的两个归档入口" aria-label="Permalink to &quot;Ubuntu 的两个归档入口&quot;">​</a></h2><p>通常：</p><ul><li>amd64 等主架构使用 <code>archive.ubuntu.com</code> / <code>security.ubuntu.com</code>；</li><li>arm64、armhf 等 ports 架构使用 <code>ports.ubuntu.com/ubuntu-ports</code>。</li></ul><p>一个镜像站支持 Ubuntu，不等于它同时、完整、及时地镜像了 <code>ubuntu</code> 与 <code>ubuntu-ports</code>。选择镜像前必须分别确认。</p><h2 id="用-deb822-明确-architecture" tabindex="-1">用 deb822 明确 Architecture <a class="header-anchor" href="#用-deb822-明确-architecture" aria-label="Permalink to &quot;用 deb822 明确 Architecture&quot;">​</a></h2><p>较新的 Ubuntu 推荐 <code>.sources</code> deb822 格式。可以为不同架构建立独立 stanza：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Types: deb</span></span>
<span class="line"><span>URIs: https://mirror.example.com/ubuntu</span></span>
<span class="line"><span>Suites: jammy jammy-updates jammy-security</span></span>
<span class="line"><span>Components: main restricted universe multiverse</span></span>
<span class="line"><span>Architectures: amd64</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Types: deb</span></span>
<span class="line"><span>URIs: https://mirror.example.com/ubuntu-ports</span></span>
<span class="line"><span>Suites: jammy jammy-updates jammy-security</span></span>
<span class="line"><span>Components: main restricted universe multiverse</span></span>
<span class="line"><span>Architectures: arm64</span></span></code></pre></div><p><code>Architectures</code> 是 APT 官方支持的多值选项，用它限制每个源需要下载的索引，避免 amd64 源去请求 arm64 路径，或反过来。语法可查 <a href="https://manpages.ubuntu.com/manpages/noble/man5/sources.list.5.html" target="_blank" rel="noreferrer">Ubuntu <code>sources.list(5)</code></a>。</p><h2 id="cross-compile-与原生-arm64-runner-是两件事" tabindex="-1">Cross compile 与原生 arm64 runner 是两件事 <a class="header-anchor" href="#cross-compile-与原生-arm64-runner-是两件事" aria-label="Permalink to &quot;Cross compile 与原生 arm64 runner 是两件事&quot;">​</a></h2><h3 id="原生-arm64-runner" tabindex="-1">原生 arm64 runner <a class="header-anchor" href="#原生-arm64-runner" aria-label="Permalink to &quot;原生 arm64 runner&quot;">​</a></h3><p><code>dpkg --print-architecture</code> 本身就是 <code>arm64</code>，只需要 arm64 archive。</p><h3 id="amd64-上-cross-compile" tabindex="-1">amd64 上 cross compile <a class="header-anchor" href="#amd64-上-cross-compile" aria-label="Permalink to &quot;amd64 上 cross compile&quot;">​</a></h3><p>主机为 amd64，同时通过：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dpkg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --add-architecture</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arm64</span></span></code></pre></div><p>安装 <code>:arm64</code> 依赖。此时必须同时配置：</p><ul><li>amd64 source，<code>Architectures: amd64</code>；</li><li>arm64 ports source，<code>Architectures: arm64</code>。</li></ul><p>否则 APT 会把所有 suite/URI 组合都尝试一遍，产生大量误导性的失败。</p><h2 id="代理与-direct-规则要和源拓扑一致" tabindex="-1">代理与 DIRECT 规则要和源拓扑一致 <a class="header-anchor" href="#代理与-direct-规则要和源拓扑一致" aria-label="Permalink to &quot;代理与 DIRECT 规则要和源拓扑一致&quot;">​</a></h2><p>CI 网络经常同时有 HTTP 代理、旁路由和内部镜像。排查时先明确每个域名应该走哪条路径：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>archive.ubuntu.com      → DIRECT 或稳定镜像</span></span>
<span class="line"><span>security.ubuntu.com     → DIRECT 或稳定镜像</span></span>
<span class="line"><span>ports.ubuntu.com        → DIRECT 或 ports 镜像</span></span>
<span class="line"><span>内部 GitLab / Harbor    → 内网直连</span></span></code></pre></div><p>不要只给 <code>archive.ubuntu.com</code> 配 DIRECT，却让 <code>ports.ubuntu.com</code> 继续经过不稳定代理；arm64 job 仍会失败。</p><h2 id="dockerhub-镜像统一走-harbor-代理" tabindex="-1">DockerHub 镜像统一走 Harbor 代理 <a class="header-anchor" href="#dockerhub-镜像统一走-harbor-代理" aria-label="Permalink to &quot;DockerHub 镜像统一走 Harbor 代理&quot;">​</a></h2><p>CI 不应让每个 runner 直接访问 DockerHub。Dockerfile 可以把基础镜像地址参数化：</p><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ARG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DOCKERHUB_PROXY</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> \${DOCKERHUB_PROXY}/ubuntu:22.04</span></span></code></pre></div><p>在 CI 中把 <code>DOCKERHUB_PROXY</code> 指向组织的 Harbor DockerHub proxy，例如 <code>\${HARBOR_HOST}/dockerhub</code>。登录时使用受保护变量和标准输入：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%s&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HARBOR_PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HARBOR_HOST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HARBOR_USERNAME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --password-stdin</span></span></code></pre></div><h2 id="一套实用诊断顺序" tabindex="-1">一套实用诊断顺序 <a class="header-anchor" href="#一套实用诊断顺序" aria-label="Permalink to &quot;一套实用诊断顺序&quot;">​</a></h2><ol><li><code>dpkg --print-architecture</code> 与 <code>--print-foreign-architectures</code>；</li><li>展开所有 <code>.list</code> / <code>.sources</code>，检查 URI、suite、Architectures；</li><li>确认镜像同时覆盖需要的 archive；</li><li>用 <code>apt-get update -o Debug::Acquire::http=true</code> 定位失败域名；</li><li>区分 DNS、代理、403、404 与 Release file 错误；</li><li>检查 runner 到内部 Harbor/GitLab 是否走直连；</li><li>最后再讨论换镜像或重试。</li></ol><p>混合架构 CI 的关键不是找一个“最快源”，而是让<strong>架构、归档路径、网络出口和缓存层一一对应</strong>。</p>`,31)])])}const m=s(n,[["render",r]]);export{u as __pageData,m as default};
